import { looksLikeLyrics, extractLyricsFromPageText } from '../lib/normalize.js';

/**
 * @returns {string|null}
 */
function parseConversationId() {
  const m = window.location.pathname.match(/\/c\/([a-z0-9-]+)/i);
  return m ? m[1] : null;
}

/**
 * @returns {string}
 */
function extractGptName() {
  const selectors = [
    '[data-testid="gpt-name"]',
    'nav img[alt] + div',
    'header h1',
    '.text-token-text-primary.truncate',
    '[class*="truncate"]',
  ];
  for (const sel of selectors) {
    const el = document.querySelector(sel);
    const t = el?.textContent?.trim();
    if (t && t.length > 1 && t.length < 120 && !/^ChatGPT$/i.test(t)) return t;
  }
  const title = document.title.replace(/\s*-\s*ChatGPT\s*$/i, '').trim();
  if (title && !/^ChatGPT$/i.test(title)) return title;
  return '';
}

/**
 * @returns {string}
 */
function extractConversationTitle() {
  const active = document.querySelector('nav a[href*="/c/"].bg-token-sidebar-surface-secondary, nav a.selected');
  if (active?.textContent?.trim()) return active.textContent.trim();
  const gpt = extractGptName();
  return gpt || 'ChatGPT 会話';
}

/**
 * @returns {HTMLElement[]}
 */
function getAssistantBlocks() {
  const blocks = [];
  const candidates = document.querySelectorAll(
    '[data-message-author-role="assistant"], article[data-testid^="conversation-turn"], .agent-turn',
  );
  candidates.forEach((el) => blocks.push(el));
  if (blocks.length) return blocks;

  document.querySelectorAll('div.markdown, .markdown.prose').forEach((el) => {
    const turn = el.closest('article, [class*="turn"]') || el;
    blocks.push(/** @type {HTMLElement} */ (turn));
  });
  return blocks;
}

/**
 * @param {HTMLElement} block
 * @returns {string}
 */
function blockText(block) {
  return (block.innerText || block.textContent || '').trim();
}

/**
 * @returns {string}
 */
function pickBestLyrics() {
  const blocks = getAssistantBlocks();
  let best = '';
  for (const block of blocks) {
    const text = blockText(block);
    if (looksLikeLyrics(text) && text.length > best.length) {
      best = text;
    }
  }
  if (best) return best;

  for (const block of blocks) {
    const text = blockText(block);
    if (text.length > best.length) best = text;
  }

  if (!best || best.length < 20) {
    const parsed = extractLyricsFromPageText(document.body?.innerText || '', extractConversationTitle());
    if (parsed.lyrics.length > best.length) best = parsed.lyrics;
  }

  return best;
}

/**
 * @returns {Partial<import('../types.js').Entry>}
 */
function extractChatGPTData() {
  const conversationId = parseConversationId();
  const sourceUrl = conversationId
    ? `${window.location.origin}/c/${conversationId}`
    : window.location.href.split('?')[0];

  const gptName = extractGptName();
  const title = extractConversationTitle();
  const lyrics = pickBestLyrics();

  return {
    source: 'chatgpt',
    title,
    lyrics,
    gptName,
    conversationId: conversationId || undefined,
    sourceUrl,
    capturedAt: new Date().toISOString(),
  };
}

async function autoCaptureIfEnabled() {
  if (!parseConversationId()) return;
  try {
    const res = await chrome.runtime.sendMessage({ action: 'getSettings' });
    if (!res?.settings?.autoSaveChatGPT) return;
    const data = extractChatGPTData();
    if (!data.lyrics && !data.title) return;
    await chrome.runtime.sendMessage({ action: 'saveEntry', data });
  } catch {
    /* ignore */
  }
}

let debounce = null;
const mo = new MutationObserver(() => {
  clearTimeout(debounce);
  debounce = setTimeout(autoCaptureIfEnabled, 2000);
});

chrome.runtime.onMessage.addListener((request, _sender, sendResponse) => {
  if (request.action === 'captureChatGPT') {
    sendResponse({ success: true, data: extractChatGPTData() });
    return true;
  }
  return false;
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    mo.observe(document.body, { childList: true, subtree: true });
    setTimeout(autoCaptureIfEnabled, 2500);
  });
} else {
  mo.observe(document.body, { childList: true, subtree: true });
  setTimeout(autoCaptureIfEnabled, 2500);
}
